from itertools import combinations

def is_triangle_free(edges, n=6):
    adj = [[False]*n for _ in range(n)]
    for u, v in edges:
        adj[u][v] = True
        adj[v][u] = True
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                if adj[i][j] and adj[j][k] and adj[i][k]:
                    return False
    return True

def is_maximal_triangle_free(edges, n=6):
    if not is_triangle_free(edges, n):
        return False
    edge_set = set(edges)
    all_possible = [(u,v) for u in range(n) for v in range(u+1,n)]
    for e in all_possible:
        if e not in edge_set:
            # Check if adding e creates a triangle
            new_edges = edges + [e]
            if is_triangle_free(new_edges, n):
                # Can add e without triangle => not maximal
                return False
    return True

# Use backtracking search
# Fixed: (3,5) must be present
all_edges = [(u,v) for u in range(6) for v in range(u+1,6)]
fixed_present = {(3,5)}

def solve():
    # Try all subsets containing (3,5)
    optional_edges = [e for e in all_edges if e not in fixed_present]

    best = None
    for mask in range(1 << len(optional_edges)):
        chosen = list(fixed_present)
        for i, e in enumerate(optional_edges):
            if mask & (1 << i):
                chosen.append(e)
        if is_maximal_triangle_free(chosen):
            if best is None or len(chosen) > len(best):
                best = chosen
    return best

result = solve()
print("Found maximal triangle-free graph:", sorted(result))
print("Number of edges:", len(result))
print("Is triangle-free:", is_triangle_free(result))
print("Is maximal:", is_maximal_triangle_free(result))
